  const child = new Deno.Command('deno', {
    args: ['task', taskName],
    cwd: options.cwd,
    env: options.env,
    stdin: 'inherit',
    stdout: 'piped',
    stderr: 'piped',
  }).spawn();

  const actionableStderrHead: string[] = [];
  const actionableStderrTail: string[] = [];
  const actionableStdoutHead: string[] = [];
  const actionableStdoutTail: string[] = [];
  let stderrBuffer = '';
  let stdoutBuffer = '';
  let timedOut = false;
  const decoder = new TextDecoder();
  function captureActionableLines(flush = false): void {
    const lines = stderrBuffer.split(/\r?\n/);
    stderrBuffer = flush ? '' : lines.pop() ?? '';
    for (const line of lines) {
      const detail = stripVTControlCharacters(line).trim();
      if (!detail || detail.startsWith('Task ')) continue;
      const boundedDetail = truncateUtf8(detail, MAX_ACTIONABLE_STDERR_LINE_BYTES);
      if (actionableStderrHead.length < ACTIONABLE_STDERR_HEAD_LINES) {
        actionableStderrHead.push(boundedDetail);
        continue;
      }
      if (actionableStderrTail.length === ACTIONABLE_STDERR_TAIL_LINES) {
        actionableStderrTail.shift();
      }
      actionableStderrTail.push(boundedDetail);
    }
  }
  const captureStderr = (async () => {
    for await (const chunk of child.stderr) {
      await Deno.stderr.write(chunk);
      stderrBuffer += decoder.decode(chunk, { stream: true });
      captureActionableLines();
    }
    stderrBuffer += decoder.decode();
    stderrBuffer += '\n';
    captureActionableLines(true);
  })();
  function captureActionableStdoutLines(flush = false): void {
    const lines = stdoutBuffer.split(/\r?\n/);
    stdoutBuffer = flush ? '' : lines.pop() ?? '';
    for (const line of lines) {
      const detail = stripVTControlCharacters(line).trim();
      if (!detail || detail.startsWith('Task ')) continue;
      const boundedDetail = truncateUtf8(detail, MAX_ACTIONABLE_STDERR_LINE_BYTES);
      if (actionableStdoutHead.length < ACTIONABLE_STDERR_HEAD_LINES) {
        actionableStdoutHead.push(boundedDetail);
        continue;
      }
      if (actionableStdoutTail.length === ACTIONABLE_STDERR_TAIL_LINES) {
        actionableStdoutTail.shift();
      }
      actionableStdoutTail.push(boundedDetail);
    }
  }
  const captureStdout = (async () => {
    const stdoutDecoder = new TextDecoder();
    for await (const chunk of child.stdout) {
      await Deno.stdout.write(chunk);
      stdoutBuffer += stdoutDecoder.decode(chunk, { stream: true });
      captureActionableStdoutLines();
    }
    stdoutBuffer += stdoutDecoder.decode();
    stdoutBuffer += '\n';
    captureActionableStdoutLines(true);
  })();

  const timeoutId = options.timeoutSeconds === undefined ? undefined : setTimeout(() => {
    try {
      child.kill('SIGTERM');
      timedOut = true;
    } catch {
