// IMPL-EVAL fixture harness: exercises a run-tool template through four scenarios.
// Usage: deno run --allow-all eval-fixture.ts <template-path> <label>
const templatePath = Deno.args[0];
const label = Deno.args[1] ?? 'run';
const template = await Deno.readTextFile(templatePath);

const PREAMBLE = 'Loaded configuration from vendor.config.ts.';
const STDERR_ERROR = 'Error: cannot open database lock file (E4501).';
const STDOUT_ERROR = 'Error: could not reach the catalog service.';

async function makeRoot(prefix: string, tasks: Record<string, string>): Promise<string> {
  const root = await Deno.makeTempDir({ prefix });
  await Deno.writeTextFile(
    join(root, 'deno.json'),
    JSON.stringify({ tasks }),
  );
  await Deno.writeTextFile(join(root, 'run-tool.mts'), template);
  return root;
}

function join(...parts: string[]): string {
  return parts.join('/');
}

async function runRequest(root: string, request: Record<string, string>, suffix: string) {
  const requestPath = join(root, 'request.json');
  const resultPath = join(root, 'result.json');
  await Deno.writeTextFile(requestPath, JSON.stringify(request));
  const cmd = new Deno.Command(Deno.execPath(), {
    args: ['run', '--allow-all', join(root, 'run-tool.mts'), '--request', requestPath, suffix],
    cwd: root,
    stdout: 'piped',
    stderr: 'piped',
  });
  const output = await cmd.output();
  let result: unknown = null;
  try {
    result = JSON.parse(await Deno.readTextFile(resultPath));
  } catch {
    result = { parseError: 'no result record' };
  }
  return { code: output.code, result };
}

async function runErrorFile(root: string, task: string) {
  const errorPath = join(root, 'tool.error');
  const cmd = new Deno.Command(Deno.execPath(), {
    args: ['run', '--allow-all', join(root, 'run-tool.mts'), errorPath, task],
    cwd: root,
    stdout: 'piped',
    stderr: 'piped',
  });
  const output = await cmd.output();
  let persisted = '';
  try {
    persisted = await Deno.readTextFile(errorPath);
  } catch {
    persisted = '(no error file)';
  }
  return {
    code: output.code,
    persistedBytes: new TextEncoder().encode(persisted).byteLength,
    persistedLines: persisted.trim().split('\n').length,
  };
}

const payloadScript = (stderrText: string, stdoutText: string, code: number) =>
  `const enc = new TextEncoder();\n` +
  (stderrText ? `await Deno.stderr.write(enc.encode(${JSON.stringify(stderrText)}));\n` : '') +
  (stdoutText ? `await Deno.stdout.write(enc.encode(${JSON.stringify(stdoutText)}));\n` : '') +
  `Deno.exit(${code});\n`;

// Scenario 1: generic informational preamble then a real error, both on stderr.
{
  const root = await makeRoot('eval-mask-', {
    'db:migrate:gen': 'deno run --allow-all payload.ts',
  });
  await Deno.writeTextFile(
    join(root, 'payload.ts'),
    payloadScript(`${PREAMBLE}\nScanning project files (3 present).\n${STDERR_ERROR}\n`, '', 16),
  );
  const outcome = await runRequest(root, {
    NETSCRIPT_PRISMA_OPERATION: 'migrate',
    NETSCRIPT_DB_RESULT_FILE: join(root, 'result.json'),
  }, 'gen');
  console.log(`[${label}] S1 masking: code=${outcome.code} message=${
    JSON.stringify((outcome.result as { message?: string }).message)
  }`);
  await Deno.remove(root, { recursive: true });
}

// Scenario 2: failure only on stdout.
{
  const root = await makeRoot('eval-stdout-', {
    'db:seed:gen': 'deno run --allow-all payload.ts',
  });
  await Deno.writeTextFile(
    join(root, 'payload.ts'),
    payloadScript('', `${STDOUT_ERROR}\n`, 16),
  );
  const outcome = await runRequest(root, {
    NETSCRIPT_PRISMA_OPERATION: 'seed',
    NETSCRIPT_DB_RESULT_FILE: join(root, 'result.json'),
  }, 'gen');
  console.log(`[${label}] S2 stdout-only: code=${outcome.code} message=${
    JSON.stringify((outcome.result as { message?: string }).message)
  }`);
  await Deno.remove(root, { recursive: true });
}

// Scenario 3: migrate action must execute the deploy task.
{
  const root = await makeRoot('eval-map-', {
    'db:migrate:gen': 'deno run --allow-all author.ts',
    'db:deploy:gen': 'deno run --allow-all deploy.ts',
  });
  await Deno.writeTextFile(join(root, 'author.ts'), payloadScript('', 'authoring attempt\n', 3));
  await Deno.writeTextFile(
    join(root, 'deploy.ts'),
    `await Deno.writeTextFile('deployed.marker', 'ok');\nDeno.exit(0);\n`,
  );
  const mapped = await runRequest(root, {
    NETSCRIPT_PRISMA_OPERATION: 'migrate',
    NETSCRIPT_PRISMA_TASK_OPERATION: 'deploy',
    NETSCRIPT_DB_RESULT_FILE: join(root, 'result.json'),
  }, 'gen');
  const marker = await Deno.readTextFile(join(root, 'deployed.marker')).catch(() => 'ABSENT');
  const legacy = await runRequest(root, {
    NETSCRIPT_PRISMA_OPERATION: 'seed',
    NETSCRIPT_DB_RESULT_FILE: join(root, 'result.json'),
  }, 'gen');
  console.log(
    `[${label}] S3 mapping: migrate+deploy code=${mapped.code} marker=${marker.trim()} | legacy seed code=${legacy.code}`,
  );
  await Deno.remove(root, { recursive: true });
}

// Scenario 4: both streams flood — measure persisted error-file bytes against the 16 KiB ceiling.
{
  const line = 'x'.repeat(600);
  const flood = Array.from({ length: 40 }, (_, i) => `${line} ${i}`).join('\n') + '\n';
  const root = await makeRoot('eval-cap-', {
    'db:seed:gen': 'deno run --allow-all payload.ts',
  });
  await Deno.writeTextFile(join(root, 'payload.ts'), payloadScript(flood, flood, 16));
  const outcome = await runErrorFile(root, 'db:seed:gen');
  console.log(
    `[${label}] S4 both-streams flood: code=${outcome.code} persistedBytes=${outcome.persistedBytes} lines=${outcome.persistedLines} over16KiB=${outcome.persistedBytes > 16384}`,
  );
  await Deno.remove(root, { recursive: true });
}

